WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/50.0/connection.js")}
{!REQUIRESCRIPT("/soap/ajax/50.0/apex.js")}

var ns = '';
var result = sforce.connection.describeGlobal();
var sobj = result.getArray("sobjects").find(sobj => sobj.name.indexOf('__BHLI_LinkedInSynchronization__c') > 0);

if (sobj) {
  ns = sobj.name.substring(0, sobj.name.indexOf('__BHLI_LinkedInSynchronization__c')) + '.';
}

sforce.apex.execute(ns + "BHLI_CandidateSyncController", "syncCandidate", {candidateId:"{!Contact.Id}"}, function(result) {
alert(result.message);

if (result.success === 'true') {
  window.location.reload();
}
}, false);
